{
  "title": "The Gilded Ruin Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team arrives at the ruined royal city.",
      "visual_description": "A crumbling archway leads into a city of broken towers and faded royal banners flapping in the wind. The party stands at the threshold, surveying the devastation.",
      "characters": ["Elena", "Kael", "Mira", "Borin"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople warn them of the dangers.",
      "visual_description": "Huddled behind a collapsed wall, a group of terrified civilians gestures frantically toward the castle, whispering of curses and dragons.",
      "characters": ["Elena", "Kael", "Mira", "Borin", "Townspeople"]
    },
    {
      "scene_number": 3,
      "caption": "The party approaches the castle gates.",
      "visual_description": "Massive iron gates, scarred by claw marks, stand half-open. Beyond them, a courtyard littered with old bones and discarded armor.",
      "characters": ["Elena", "Kael", "Mira", "Borin"]
    },
    {
      "scene_number": 4,
      "caption": "An armored patrol challenges them.",
      "visual_description": "Four figures in dented, mismatched armor step from the shadows, weapons drawn. Their eyes glow faintly with cursed light.",
      "characters": ["Elena", "Kael", "Mira", "Borin", "Armored Patrol"]
    },
    {
      "scene_number": 5,
      "caption": "Kael negotiates a tense standoff.",
      "visual_description": "Kael raises his hands, speaking calmly while Elena and Mira keep their hands near their weapons. Borin grips his axe, ready.",
      "characters": ["Elena", "Kael", "Mira", "Borin", "Armored Patrol"]
    },
    {
      "scene_number": 6,
      "caption": "They enter a cursed tower rumored to hold the prisoner.",
      "visual_description": "A spiral staircase winds upward, walls covered in glowing runes. Strange whispers echo from the stones.",
      "characters": ["Elena", "Kael", "Mira", "Borin"]
    },
    {
      "scene_number": 7,
      "caption": "Mira disarms a magical trap on the door.",
      "visual_description": "Mira kneels before a ornate stone door inscribed with pulsing sigils. She traces a counter-rune, and the glow fades.",
      "characters": ["Mira"]
    },
    {
      "scene_number": 8,
      "caption": "The door opens to reveal a treasure room, a temptation.",
      "visual_description": "Golden coins, jewels, and enchanted weapons spill from chests. A magical aura shimmers over the hoard.",
      "characters": ["Elena", "Kael", "Mira", "Borin"]
    },
    {
      "scene_number": 9,
      "caption": "Borin resists the lure of gold.",
      "visual_description": "Borin stares at a jeweled axe, his hand trembling, but he turns away with a grunt, remembering their mission.",
      "characters": ["Borin"]
    },
    {
      "scene_number": 10,
      "caption": "They find the prisoner in a high chamber.",
      "visual_description": "A lone figure in tattered robes stands chained to a pillar, a faint magical barrier humming around them.",
      "characters": ["Elena", "Kael", "Mira", "Borin", "Prisoner"]
    },
    {
      "scene_number": 11,
      "caption": "Elena shatters the barrier with a spell.",
      "visual_description": "Elena channels light from her hands, striking the magical barrier which cracks and explodes in shards of energy.",
      "characters": ["Elena", "Prisoner"]
    },
    {
      "scene_number": 12,
      "caption": "A dragon's roar shakes the tower.",
      "visual_description": "The tower trembles as a massive shadow passes outside the window. A reptilian eye glares through the opening.",
      "characters": ["Elena", "Kael", "Mira", "Borin", "Prisoner"]
    },
    {
      "scene_number": 13,
      "caption": "They flee down the tower as it begins to collapse.",
      "visual_description": "Stones rain from the ceiling as the party races down the spiraling stairs. Kael helps the prisoner keep pace.",
      "characters": ["Elena", "Kael", "Mira", "Borin", "Prisoner"]
    },
    {
      "scene_number": 14,
      "caption": "They burst into the courtyard, facing the dragon.",
      "visual_description": "A great crimson dragon lands before them, wings spread, fire flickering in its throat. The party forms a defensive line.",
      "characters": ["Elena", "Kael", "Mira", "Borin", "Prisoner", "Dragon"]
    },
    {
      "scene_number": 15,
      "caption": "Mira blinds the dragon with a flash bomb.",
      "visual_description": "Mira hurls a small orb that explodes in brilliant light. The dragon rears back, roaring in confusion.",
      "characters": ["Mira", "Dragon"]
    },
    {
      "scene_number": 16,
      "caption": "The party races across a crumbling bridge.",
      "visual_description": "A narrow stone bridge spans a chasm, sections falling away as they run. The dragon pursues from above.",
      "characters": ["Elena", "Kael", "Mira", "Borin", "Prisoner", "Dragon"]
    },
    {
      "scene_number": 17,
      "caption": "Kael cuts the bridge supports, dropping the dragon.",
      "visual_description": "Kael swings his sword at a rope holding a heavy counterweight. The bridge collapses behind them, taking the dragon into the gorge.",
      "characters": ["Kael", "Dragon"]
    },
    {
      "scene_number": 18,
      "caption": "The survivors emerge from the ruins, free.",
      "visual_description": "The party stands on a hill overlooking the ruined city, the prisoner safe among them. The sun breaks through the clouds.",
      "characters": ["Elena", "Kael", "Mira", "Borin", "Prisoner"]
    }
  ]
}

